def count_zeros(n):
    return str(n).count('0')

M = 10**1000 - 1
Ns = [2, 3, 4, 5, 6, 7, 8, 9, 13]
results = {}

for N in Ns:
    Q = (M // N)
    A = count_zeros(Q)
    results[N] = A

print(results)

